<script lang="ts">import { previewFeature } from '@fex-design/core/upload/features/preview'; import { uploadFeature } from '@fex-design/core/upload/features/upload'; import { UploadRoot, UploadTrigger, createUpload } from '@fex-design/svelte/primitive/upload'; import Button from '@fex-design/svelte/ui/button'; import { uploadBody, uploadServerUrl } from './api'; import DemoList from './demo-list.svelte'; import DemoSection from './demo-section.svelte'; const upload = createUpload({ maxCount: 1, features: [uploadFeature({ request: ({ file, signal, onProgress }) => uploadBody(`${uploadServerUrl}/upload`, file, { fileName: file.name, signal, onProgress }) }), previewFeature()] })</script>
<DemoSection title="单文件上传" description="向本地 Node 服务发送真实请求，maxCount 保证列表中只保留一个文件。"><UploadRoot controller={upload}><UploadTrigger>{#snippet children(value)}<Button {...value.props}>选择一个文件</Button>{/snippet}</UploadTrigger><DemoList /></UploadRoot></DemoSection>
